import java.util.*; public class TollBooth { record Vehicle(String number,String type){} public static void main(String[] z){Scanner s=new Scanner(System.in);int total=0,b=0,c=0,t=0;while(true){System.out.print("Vehicle number (done to stop): ");String n=s.next();if(n.equalsIgnoreCase("done"))break;System.out.print("Type (bike/car/truck): ");Vehicle v=new Vehicle(n,s.next().toLowerCase());int fee=switch(v.type()){case "bike"->{b++;yield 20;}case "car"->{c++;yield 50;}case "truck"->{t++;yield 150;}default->throw new IllegalArgumentException("Unknown type");};total+=fee;}System.out.println("Total toll: "+total);System.out.println("Most frequent: "+(b>=c&&b>=t?"bike":c>=t?"car":"truck"));}}
